head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getCellReadOnly]<br/>Row 인덱스와 Column 정보를 사용하여 특정 Cell 의 readOnly 속성값을 반환합니다.",
    "validation" : [
        "rowIndex(필수) 파라미터로 readOnly 속성값을 조회할 특정 Cell 의 Row 인덱스를 설정할 수 있어야 합니다.",
        "colInfo(필수) 파라미터로 readOnly 속성값을 조회할 특정 Cell 의 Column 인덱스를 설정할 수 있어야 합니다.",
        "setCellReadOnly() 메소드로 readOnly 속성을 설정하지 않은 Cell 은 빈 문자열을 반환해야 합니다.",
        "반환값이 빈 문자열인 Cell 은 상위 모듈의 읽기 전용(readonly) 상태가 적용되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="Cell(0,0)/(3,3) 은 readOnly 설정, Cell(1,2)/(2,2) 는 readOnly 해제, Column 1 은 숨겨진 상태"', '', 'label1');

    // 조건 설정
    let properties = {
        dataList: "data:dlt_bind",
        readOnlyBackgroundColor: "#D3D3D3",
    };

    let cList = $c.gcm.createCList(properties);

    // dataList 생성
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성
    await $c.gcm.createBasicGridView(cList);

    // 두번째 컬럼 숨김
    target1.setColumnVisible(1, false);

    // Cell(0,0)/(3,3) 에 readOnly 설정
    target1.setCellReadOnly(0, 0, true);
    target1.setCellReadOnly(3, 3, true);
    // Cell(1,2)/(2,2) 에 readOnly 해제
    target1.setCellReadOnly(1, 2, false);
    target1.setCellReadOnly(2, 2, false);
}



scwin.btn_getCellReadOnly_onclick = function () {
    let rowIndex = Number(par_rowIndex.getText());
    let colInfo = Number(par_colInfo.getText());

    let rtn = target1.getCellReadOnly(rowIndex, colInfo);
    wf_body_bottom.getObj("scwin").setReturnValue("getCellReadOnly(" + rowIndex + ", " + colInfo + ") : " + rtn);
}
